SELECT count(*) FROM public.lineitem lineitem WHERE EXISTS (SELECT 1 FROM public.orders o, public.customer c, public.nation n, public.region r, public.part p WHERE o.o_orderkey = lineitem.l_orderkey AND c.c_custkey = o.o_custkey AND n.n_nationkey = c.c_nationkey AND r.r_regionkey = n.n_regionkey AND r.r_name = 'AMERICA' AND p.p_partkey = lineitem.l_partkey AND p.p_type = 'ECONOMY ANODIZED STEEL') AND NOT EXISTS (SELECT 1 FROM public.orders o, public.customer c WHERE o.o_orderkey = lineitem.l_orderkey AND c.c_custkey = o.o_custkey AND c.c_acctbal < 0);
